package org.sonatype.nexus.repository.openformats.huggingface;
@org.springframework.stereotype.Component @org.springframework.context.annotation.Scope("prototype") @org.springframework.beans.factory.annotation.Qualifier("huggingface") public class HuggingfaceContent extends org.sonatype.nexus.repository.openformats.OpenContentFacet { public HuggingfaceContent(@org.springframework.beans.factory.annotation.Qualifier("huggingface") org.sonatype.nexus.repository.content.store.FormatStoreManager store) { super(store); } @Override protected String determineContentType(org.sonatype.nexus.repository.content.Asset asset,org.sonatype.nexus.blobstore.api.Blob blob,boolean strict) { if(asset.path().contains("/resolve/")||asset.path().contains("/raw/"))return blob.getHeaders().getOrDefault(org.sonatype.nexus.blobstore.api.BlobStore.CONTENT_TYPE_HEADER,"application/octet-stream");return super.determineContentType(asset,blob,strict); } }
